52	static QString getLocalDateTimeWithUtcOffset()
53	{
54	    QDateTime currentDateTime = QDateTime::currentDateTime();
55	    int year = currentDateTime.date().year();
56	    int month = currentDateTime.date().month();
57	    int day = currentDateTime.date().day();
58	    int hour = currentDateTime.time().hour();
59	    int minute = currentDateTime.time().minute();
60	    int second = currentDateTime.time().second();
61	    int utcOffset = currentDateTime.offsetFromUtc() / 3600;
62	    int utcOffsetMinute = (currentDateTime.offsetFromUtc() % 3600) / 60;
63	    QString dateTimeString = QString("%1/%2/%3 %4:%5:%6 UTC%7%8:%9")
64	        .arg(year, 4, 10, QChar('0'))
65	        .arg(month, 2, 10, QChar('0'))
66	        .arg(day, 2, 10, QChar('0'))
67	        .arg(hour, 2, 10, QChar('0'))
68	        .arg(minute, 2, 10, QChar('0'))
69	        .arg(second, 2, 10, QChar('0'))
70	        .arg(utcOffset > 0 ? "+" : "-") // Add a plus sign for positive offsets
71	        .arg(qAbs(utcOffset), 2, 10, QChar('0'))
72	        .arg(utcOffsetMinute, 2, 10, QChar('0'));
73	    return dateTimeString;
74	}
