76	CalDevice::CalDevice(QString serial) :
77	    usb(new USBDevice(serial))
78	{
79	    loadThread = nullptr;
80	    transferActive = false;
81	
82	    // Check device identification
83	    auto id = usb->Query("*IDN?");
84	    if(!id.startsWith("LibreCAL,")) {
85	        delete usb;
86	        throw std::runtime_error("Invalid response to *IDN?: "+id.toStdString());
87	    }
88	
89	    firmware = usb->Query(":FIRMWARE?");
90	    QList<QString> fw_version = firmware.split(".");
91	    if (fw_version.size() == 3) {
92	        int firmware_major = fw_version[0].toInt();
93	        int firmware_minor = fw_version[1].toInt();
94	        this->firmware_major_minor = firmware_major + ((float)firmware_minor/10.0f);
95	        if(this->firmware_major_minor >= 0.2)
96	        {
97	            /* Set Date Time UTC */
98	            QString LocalDateTimeWithUtcOffset = getLocalDateTimeWithUtcOffset();
99	            QString ret = usb->Query(":DATE_TIME "+LocalDateTimeWithUtcOffset);
100	        }
101	    } else {
102	        // fw_version invalid
103	        this->firmware_major_minor = 0.0;
104	    }
105	    QString ports = usb->Query(":PORTS?");
106	    bool okay;
107	    numPorts = ports.toInt(&okay);
108	    if(!okay) {
109	        numPorts = 0;
110	    }
111	    connect(usb, &USBDevice::communicationFailure, this, &CalDevice::disconnected);
112	    connect(this, &CalDevice::updateCoefficientsDone, this, [=]() {
113	        transferActive = false;
114	    });
115	
116	    // Check if this device was affected by the factory calibration problem
117	    if(factoryProblemSerials.contains(usb->serial())) {
118	        // it was, check if it still has bad factory coefficients
119	
120	        struct point {
121	            uint16_t pointNum;
122	            double freq;
123	        };
124	        std::array<point, 3> pointsToCheck = {{
125	            {.pointNum = 451, .freq = 1.0},
126	            {.pointNum = 551, .freq = 2.0},
127	            {.pointNum = 651, .freq = 3.0},
128	        }};
129	
130	        bool hasBadData = false;
131	        for(auto point : pointsToCheck) {
132	            // grab the point (just checking P12_THROUGH is enough
133	            QString ret = usb->Query(":COEFF:GET? FACTORY P12_THROUGH "+QString::number(point.pointNum));
134	            auto parts = ret.split(",");
135	            if (parts.size() == 9 && parts[0].toDouble() == point.freq) {
136	                // got the correct data, check S12 phase
137	                auto S12 = std::complex(parts[3].toDouble(), parts[4].toDouble());
138	                auto constexpr expectedS12Delay = 498e-12;
139	                auto expectedS12Phase = expectedS12Delay * (point.freq * 1e9) * 2*M_PI;
140	                auto phase = -arg(S12);
141	                // unwrap to expected phase
142	                while(phase < expectedS12Phase - M_PI) {
143	                    phase += 2*M_PI;
144	                }
145	                double S12Delay = phase / (2*M_PI) / (point.freq * 1e9);
146	                qDebug() << "expected delay:" << expectedS12Delay << "factory calibration delay:" << S12Delay;
147	                auto error = S12Delay - expectedS12Delay;
148	                double tolerance = 17e-12;
149	                if(abs(error) > tolerance) {
150	                    hasBadData = true;
151	                    break;
152	                }
153	//                QList<double> possibleErrors({0, -94.7e-12, 34.8e-12});
154	//                for(auto e : possibleErrors) {
155	//                    if(abs(error-e) <= tolerance) {
156	//                        // this is the error of the LibreCAL
157	//                        if(e != 0) {
158	//                            // still has the wrong coefficients
159	//                            hasBadData = true;
160	//                        }
161	//                        break;
162	//                    }
163	//                }
164	            } else {
165	                qWarning() << "Unexpected point frequency, factory calibration data is dubious";
166	            }
167	            if(hasBadData) {
168	                break;
169	            }
170	        }
171	        if(hasBadData) {
172	            if(InformationBox::AskQuestion("Update Factory Coefficients?", "Your LibreCAL with serial number "+usb->serial()+" is affected by "
173	                                          "a mistake in the factory calibration and its factory coefficients (specifically the phase of all "
174	                                          "THRU standard definitions) are slightly wrong. The mistake has been corrected and updated factory "
175	                                          "coefficients are available. Do you want to update the factory coefficients now?", false)) {
176	                factoryUpdateDialog();
177	            }
178	        }
179	    }
180	}
