187	QString CalDevice::StandardToString(CalDevice::Standard s)
188	{
189	    switch(s.type) {
190	    case Standard::Type::Open: return "OPEN";
191	    case Standard::Type::Short: return "SHORT";
192	    case Standard::Type::Load: return "LOAD";
193	    case Standard::Type::Through: return "THROUGH "+QString::number(s.throughDest);
194	    case Standard::Type::None: return "NONE";
195	    }
196	    return "Invalid";
197	}
198	
199	CalDevice::Standard CalDevice::StandardFromString(QString s)
200	{
201	    for(auto standard : availableStandards()) {
202	        if(s == StandardToString(standard)) {
203	            return standard;
204	        }
205	    }
206	    return Standard(Standard::Type::None);
207	}
