209	CalDevice::Standard CalDevice::getStandard(int port)
210	{
211	    auto query = ":PORT? "+QString::number(port);
212	    auto response = usb->Query(query);
213	    return StandardFromString(response);
214	}
215	
216	bool CalDevice::setStandard(int port, CalDevice::Standard s)
217	{
218	    auto cmd = ":PORT "+QString::number(port)+" "+StandardToString(s);
219	    return usb->Cmd(cmd);
220	}
