222	std::vector<CalDevice::Standard> CalDevice::availableStandards()
223	{
224	    return {Standard(Standard::Type::None), Standard(Standard::Type::Open), Standard(Standard::Type::Short), Standard(Standard::Type::Load), Standard(1), Standard(2), Standard(3), Standard(4)};
225	}
