275	QString CalDevice::getDateTimeUTC()
276	{
277	    if(this->firmware_major_minor >= 0.2)
278	    {
279	        return usb->Query(":DATE_TIME?");
280	    }else
281	    {
282	        return ""; // Not available
283	    }
284	}
285	
286	void CalDevice::loadCoefficientSets(QStringList names, QList<int> ports, bool fast)
287	{
288	    coeffSets.clear();
289	
290	    if(ports.isEmpty()) {
291	        for(unsigned int i=1;i<=getNumPorts();i++) {
292	            ports.append(i);
293	        }
294	    } else {
295	        // make sure we are sorted, otherwise the through coefficient naming is wrong
296	        std::sort(ports.begin(), ports.end());
297	    }
298	
299	    abortLoading = false;
300	    transferActive = true;
301	    if(fast && Util::firmwareEqualOrHigher(firmware, "0.2.1")) {
302	        loadThread = new std::thread(&CalDevice::loadCoefficientSetsThreadFast, this, names, ports);
303	    } else {
304	        loadThread = new std::thread(&CalDevice::loadCoefficientSetsThreadSlow, this, names, ports);
305	    }
306	}
307	
308	void CalDevice::abortCoefficientLoading()
309	{
310	    if(loadThread) {
311	        abortLoading = true;
312	        loadThread->join();
313	        loadThread = nullptr;
314	        transferActive = false;
315	    }
316	}
317	
318	void CalDevice::saveCoefficientSets()
319	{
320	    if(!hasModifiedCoefficients()) {
321	        // nothing to do, already done
322	        emit updateCoefficientsDone(true);
323	    } else {
324	        transferActive = true;
325	        new std::thread(&CalDevice::saveCoefficientSetsThread, this);
326	    }
327	}
328	
329	void CalDevice::loadCoefficientSetsThreadSlow(QStringList names, QList<int> ports)
330	{
331	    QStringList coeffList = getCoefficientSetNames();
332	    if(coeffList.empty()) {
333	        // something went wrong
334	        emit updateCoefficientsDone(false);
335	        return;
336	    }
337	    if(names.size() > 0) {
338	        // check if all the requested names are actually available
339	        for(auto n : names) {
340	            if(!coeffList.contains(n)) {
341	                // this coefficient does not exist
342	                emit updateCoefficientsDone(false);
343	                return;
344	            }
345	        }
346	        coeffList = names;
347	    }
348	    // get total number of coefficient points for accurate percentage calculation
349	    unsigned long totalPoints = 0;
350	    for(auto name : coeffList) {
351	        for(int idx=0;idx<ports.size();idx++) {
352	            int i = ports[idx];
353	            if(abortLoading) {
354	                return;
355	            }
356	            totalPoints += usb->Query(":COEFF:NUM? "+name+" P"+QString::number(i)+"_OPEN").toInt();
357	            totalPoints += usb->Query(":COEFF:NUM? "+name+" P"+QString::number(i)+"_SHORT").toInt();
358	            totalPoints += usb->Query(":COEFF:NUM? "+name+" P"+QString::number(i)+"_LOAD").toInt();
359	            for(int jdx=idx+1;jdx<numPorts;jdx++) {
360	                int j = ports[jdx];
361	                totalPoints += usb->Query(":COEFF:NUM? "+name+" P"+QString::number(i)+QString::number(j)+"_THROUGH").toInt();
362	            }
363	        }
364	    }
365	    unsigned long readPoints = 0;
366	    int lastPercentage = 0;
367	    for(auto name : coeffList) {
368	        // create the coefficient set
369	        CoefficientSet set;
370	        set.name = name;
371	        set.ports = numPorts;
372	        // Read this coefficient set
373	        for(int idx=0;idx<ports.size();idx++) {
374	            int i = ports[idx];
375	            auto createCoefficient = [&](QString setName, QString paramName) -> CoefficientSet::Coefficient* {
376	                int points = usb->Query(":COEFF:NUM? "+setName+" "+paramName).toInt();
377	                CoefficientSet::Coefficient *c = new CoefficientSet::Coefficient();
378	                if(paramName.endsWith("THROUGH")) {
379	                    c->t = Touchstone(2);
380	                } else {
381	                    c->t = Touchstone(1);
382	                }
383	                for(int i=0;i<points;i++) {
384	                    if(abortLoading) {
385	                        break;
386	                    }
387	                    QString pString = usb->Query(":COEFF:GET? "+setName+" "+paramName+" "+QString::number(i));
388	                    QStringList values = pString.split(",");
389	                    Touchstone::Datapoint p;
390	                    p.frequency = values[0].toDouble() * 1e9;
391	                    for(int j = 0;j<(values.size()-1)/2;j++) {
392	                        double real = values[1+j*2].toDouble();
393	                        double imag = values[2+j*2].toDouble();
394	                        p.S.push_back(complex<double>(real, imag));
395	                    }
396	                    if(p.S.size() == 4) {
397	                        // S21 and S12 are swapped in the touchstone file order (S21 goes first)
398	                        // but Touchstone::AddDatapoint expects S11 S12 S21 S22 order. Swap to match that
399	                        swap(p.S[1], p.S[2]);
400	                    }
401	                    c->t.AddDatapoint(p);
402	                    readPoints++;
403	                    int newPercentage = readPoints * 100 / totalPoints;
404	                    if(newPercentage != lastPercentage) {
405	                        lastPercentage = newPercentage;
406	                        emit updateCoefficientsPercent(newPercentage);
407	                    }
408	                }
409	                c->t.setFilename("LibreCAL/"+paramName);
410	                return c;
411	            };
412	            set.opens[i] = (createCoefficient(name, "P"+QString::number(i)+"_OPEN"));
413	            set.shorts[i] = (createCoefficient(name, "P"+QString::number(i)+"_SHORT"));
414	            set.loads[i] = (createCoefficient(name, "P"+QString::number(i)+"_LOAD"));
415	            for(int jdx=idx+1;jdx<ports.size();jdx++) {
416	                int j = ports[jdx];
417	                set.throughs[set.portsToThroughIndex(i, j)] = createCoefficient(name, "P"+QString::number(i)+QString::number(j)+"_THROUGH");
418	            }
419	            if(abortLoading) {
420	                return;
421	            }
422	        }
423	        coeffSets.push_back(set);
424	    }
425	    emit updateCoefficientsDone(true);
426	}
