428	void CalDevice::loadCoefficientSetsThreadFast(QStringList names, QList<int> ports)
429	{
430	    QStringList coeffList = getCoefficientSetNames();
431	    if(coeffList.empty()) {
432	        // something went wrong
433	        emit updateCoefficientsDone(false);
434	        return;
435	    }
436	    if(names.size() > 0) {
437	        // check if all the requested names are actually available
438	        for(auto n : names) {
439	            if(!coeffList.contains(n)) {
440	                // this coefficient does not exist
441	                emit updateCoefficientsDone(false);
442	                return;
443	            }
444	        }
445	        coeffList = names;
446	    }
447	
448	    int total_coeffs = (ports.size() * 3 + ports.size() * (ports.size() - 1) / 2) * coeffList.size();
449	    int read_coeffs = 0;
450	
451	    for(auto name : coeffList) {
452	        // create the coefficient set
453	        CoefficientSet set;
454	        set.name = name;
455	        set.ports = numPorts;
456	
457	        auto createCoefficient = [&](QString setName, QString paramName) -> CoefficientSet::Coefficient* {
458	            CoefficientSet::Coefficient *c = new CoefficientSet::Coefficient();
459	            // ask for the whole set at once
460	            usb->flushReceived();
461	            usb->send(":COEFF:GET? "+setName+" "+paramName);
462	            // handle incoming lines
463	            if(paramName.endsWith("THROUGH")) {
464	                c->t = Touchstone(2);
465	            } else {
466	                c->t = Touchstone(1);
467	            }
468	            c->t.setFilename("LibreCAL/"+paramName);
469	            while(true) {
470	                QString line;
471	                if(!usb->receive(&line)) {
472	                    // failed to receive something, abort
473	                    return nullptr;
474	                }
475	                if(line.startsWith("ERROR")) {
476	                    // something went wront
477	                    return nullptr;
478	                }
479	                // ignore start, comments and option line
480	                if(line.startsWith("START") || line.startsWith("!") || line.startsWith("#")) {
481	                    // ignore
482	                    continue;
483	                }
484	                if(line.startsWith("END")) {
485	                    // got all data
486	                    return c;
487	                }
488	                // parse the values
489	                try {
490	                    QStringList values = line.split(" ");
491	                    Touchstone::Datapoint p;
492	                    p.frequency = values[0].toDouble() * 1e9;
493	                    for(int j = 0;j<(values.size()-1)/2;j++) {
494	                        double real = values[1+j*2].toDouble();
495	                        double imag = values[2+j*2].toDouble();
496	                        p.S.push_back(complex<double>(real, imag));
497	                    }
498	                    if(p.S.size() == 4) {
499	                        // S21 and S12 are swapped in the touchstone file order (S21 goes first)
500	                        // but Touchstone::AddDatapoint expects S11 S12 S21 S22 order. Swap to match that
501	                        swap(p.S[1], p.S[2]);
502	                    }
503	                    c->t.AddDatapoint(p);
504	                } catch (...) {
505	                    return nullptr;
506	                }
507	            }
508	        };
509	
510	        for(int idx=0;idx<ports.size();idx++) {
511	            int i = ports[idx];
512	
513	            auto c = createCoefficient(name, "P"+QString::number(i)+"_OPEN");
514	            if(abortLoading) {
515	                return;
516	            }
517	            if(c) {
518	                set.opens[i] = c;
519	            }
520	            read_coeffs++;
521	            emit updateCoefficientsPercent(read_coeffs * 100 / total_coeffs);
522	
523	            c = createCoefficient(name, "P"+QString::number(i)+"_SHORT");
524	            if(abortLoading) {
525	                return;
526	            }
527	            if(c) {
528	                set.shorts[i] = c;
529	            }
530	            read_coeffs++;
531	            emit updateCoefficientsPercent(read_coeffs * 100 / total_coeffs);
532	
533	            c = createCoefficient(name, "P"+QString::number(i)+"_LOAD");
534	            if(abortLoading) {
535	                return;
536	            }
537	            if(c) {
538	                set.loads[i] = c;
539	            }
540	            read_coeffs++;
541	            emit updateCoefficientsPercent(read_coeffs * 100 / total_coeffs);
542	
543	            for(int jdx=idx+1;jdx<ports.size();jdx++) {
544	                int j = ports[jdx];
545	
546	                c = createCoefficient(name, "P"+QString::number(i)+QString::number(j)+"_THROUGH");
547	                if(abortLoading) {
548	                    return;
549	                }
550	                if(c) {
551	                    set.throughs[set.portsToThroughIndex(i, j)] = c;
552	                }
553	                read_coeffs++;
554	                emit updateCoefficientsPercent(read_coeffs * 100 / total_coeffs);
555	            }
556	        }
557	
558	        coeffSets.push_back(set);
559	    }
560	    emit updateCoefficientsDone(true);
561	}
