563	void CalDevice::saveCoefficientSetsThread()
564	{
565	    // figure out how many points need to be transferred
566	    unsigned long totalPoints = 0;
567	    for(auto set : coeffSets) {
568	        for(auto c : set.opens) {
569	            if(c.second->modified) {
570	                totalPoints += c.second->t.points();
571	            }
572	        }
573	        for(auto c : set.shorts) {
574	            if(c.second->modified) {
575	                totalPoints += c.second->t.points();
576	            }
577	        }
578	        for(auto c : set.loads) {
579	            if(c.second->modified) {
580	                totalPoints += c.second->t.points();
581	            }
582	        }
583	        for(auto c : set.throughs) {
584	            if(c.second->modified) {
585	                totalPoints += c.second->t.points();
586	            }
587	        }
588	    }
589	    unsigned long transferredPoints = 0;
590	    int lastPercentage = 0;
591	    bool success = true;
592	    for(auto set : coeffSets) {
593	        auto createCoefficient = [&](QString setName, QString paramName, Touchstone &t, bool &modified) -> bool {
594	            if(!modified) {
595	                // no changes, nothing to do
596	                return true;
597	            }
598	            int points = t.points();
599	            if(points > 0) {
600	                // create the file
601	                if(!usb->Cmd(":COEFF:CREATE "+setName+" "+paramName)) {
602	                    return false;
603	                }
604	                for(int i=0;i<points;i++) {
605	                    auto point = t.point(i);
606	                    if(point.S.size() == 4) {
607	                        // S parameters in point are in S11 S12 S21 S22 order but the LibreCAL expects
608	                        // S11 S21 S12 S22 (according to the two port touchstone format. Swap here.
609	                        swap(point.S[1], point.S[2]);
610	                    }
611	                    QString cmd = ":COEFF:ADD "+QString::number(point.frequency / 1000000000.0);
612	                    for(auto s : point.S) {
613	                        cmd += " "+QString::number(s.real())+" "+QString::number(s.imag());
614	                    }
615	                    if(!usb->Cmd(cmd)) {
616	                        return false;
617	                    }
618	                    transferredPoints++;
619	                    int newPercentage = transferredPoints * 100 / totalPoints;
620	                    if(newPercentage != lastPercentage) {
621	                        lastPercentage = newPercentage;
622	                        emit updateCoefficientsPercent(newPercentage);
623	                    }
624	                }
625	                if(!usb->Cmd(":COEFF:FIN")) {
626	                    return false;
627	                }
628	            } else {
629	                // no points, delete coefficient
630	                if(!usb->Cmd(":COEFF:DEL "+setName+" "+paramName)) {
631	                    return false;
632	                }
633	            }
634	            modified = false;
635	            return true;
636	        };
637	        for(int i=1;i<=numPorts;i++) {
638	            if(set.opens.count(i)) {
639	                success &= createCoefficient(set.name, "P"+QString::number(i)+"_OPEN", set.opens[i]->t, set.opens[i]->modified);
640	                if(!success) {
641	                    break;
642	                }
643	            }
644	            if(set.shorts.count(i)) {
645	                success &= createCoefficient(set.name, "P"+QString::number(i)+"_SHORT", set.shorts[i]->t, set.shorts[i]->modified);
646	                if(!success) {
647	                    break;
648	                }
649	            }
650	            if(set.loads.count(i)) {
651	                success &= createCoefficient(set.name, "P"+QString::number(i)+"_LOAD", set.loads[i]->t, set.loads[i]->modified);
652	                if(!success) {
653	                    break;
654	                }
655	            }
656	            for(int j=i+1;j<=numPorts;j++) {
657	                auto c = set.getThrough(i,j);
658	                if(c) {
659	                    success &= createCoefficient(set.name, "P"+QString::number(i)+QString::number(j)+"_THROUGH", c->t, c->modified);
660	                    if(!success) {
661	                        break;
662	                    }
663	                }
664	            }
665	            if(!success) {
666	                break;
667	            }
668	        }
669	    }
670	    // prune empty coefficient sets
671	    auto i = coeffSets.begin();
672	    while(i != coeffSets.end()) {
673	        if(i->isEmpty()) {
674	            i = coeffSets.erase(i);
675	        } else {
676	            i++;
677	        }
678	    }
679	    emit updateCoefficientsDone(success);
680	}
