732	void CalDevice::factoryUpdateDialog()
733	{
734	    auto d = new QDialog();
735	    auto ui = new Ui::FactoryUpdateDialog();
736	    ui->setupUi(d);
737	
738	    ui->progress->setValue(0);
739	    connect(this, &CalDevice::updateCoefficientsPercent, ui->progress, &QProgressBar::setValue, Qt::QueuedConnection);
740	
741	    auto updateEnableState = [=]() {
742	        ui->updateFile->setEnabled(true);
743	        ui->updateServer->setEnabled(true);
744	        if(ui->updateServer->isChecked()) {
745	            // can start
746	            ui->startUpdate->setEnabled(true);
747	            // file selection disabled
748	            ui->file->setEnabled(false);
749	            ui->browse->setEnabled(false);
750	        } else {
751	            // file selection enabled
752	            ui->file->setEnabled(true);
753	            ui->browse->setEnabled(true);
754	            // start possible if some file is selected
755	            ui->startUpdate->setEnabled(!ui->file->text().isEmpty());
756	        }
757	    };
758	
759	    connect(ui->updateServer, &QRadioButton::toggled, this, updateEnableState);
760	    connect(ui->file, &QLineEdit::textChanged, this, updateEnableState);
761	    connect(ui->browse, &QPushButton::clicked, this, [=](){
762	        auto filename = QFileDialog::getOpenFileName(nullptr, "Select factory coefficient file", "", "Zip files (*.zip)", nullptr, QFileDialog::DontUseNativeDialog);
763	        if(filename.isEmpty()) {
764	            // aborted selection
765	            return;
766	        } else {
767	            ui->file->setText(filename);
768	            updateEnableState();
769	        }
770	    });
771	
772	    auto addStatus = [=](QString status) {
773	        ui->msg->appendPlainText(status);
774	    };
775	    auto abortWithError = [=](QString error) {
776	        ui->progress->setValue(0);
777	
778	        QTextCharFormat tf;
779	        tf = ui->msg->currentCharFormat();
780	        tf.setForeground(QBrush(Qt::red));
781	        ui->msg->setCurrentCharFormat(tf);
782	        ui->msg->appendPlainText(error);
783	        tf.setForeground(QBrush(Qt::black));
784	        ui->msg->setCurrentCharFormat(tf);
785	
786	        updateEnableState();
787	    };
788	
789	    connect(this, &CalDevice::updateCoefficientsDone, this, [=](bool success) {
790	        // transfer complete
791	
792	        // pass on communication failures again
793	        connect(usb, &USBDevice::communicationFailure, this, &CalDevice::disconnected);
794	        if(success) {
795	            ui->progress->setValue(100);
796	            addStatus("...done");
797	            updateEnableState();
798	        } else {
799	            abortWithError("Transferring coefficients to LibreCAL failed");
800	        }
801	    });
802	
803	    auto updateFromFile = [=](QString filename) {
804	        addStatus("Unzipping file...");
805	        if(!QMicroz::extract(filename, ".")) {
806	            abortWithError("Extracting zip file failed");
807	            return;
808	        }
809	        // create coefficient set
810	        auto set = CoefficientSet();
811	        set.name = "FACTORY";
812	        set.ports = 4;
813	        set.createEmptyCoefficients();
814	        struct Coeff {
815	            QString description;
816	            QString filename;
817	            CoefficientSet::Coefficient *coeff;
818	        };
819	        std::array<Coeff, 18> coeffs = {{
820	                                         {.description = "Port 1 open", .filename = "P1_OPEN.s1p", .coeff = set.opens[1]},
821	                                         {.description = "Port 1 short", .filename = "P1_SHORT.s1p", .coeff = set.shorts[1]},
822	                                         {.description = "Port 1 load", .filename = "P1_LOAD.s1p", .coeff = set.loads[1]},
823	                                         {.description = "Port 2 open", .filename = "P2_OPEN.s1p", .coeff = set.opens[2]},
824	                                         {.description = "Port 2 short", .filename = "P2_SHORT.s1p", .coeff = set.shorts[2]},
825	                                         {.description = "Port 2 load", .filename = "P2_LOAD.s1p", .coeff = set.loads[2]},
826	                                         {.description = "Port 3 open", .filename = "P3_OPEN.s1p", .coeff = set.opens[3]},
827	                                         {.description = "Port 3 short", .filename = "P3_SHORT.s1p", .coeff = set.shorts[3]},
828	                                         {.description = "Port 3 load", .filename = "P3_LOAD.s1p", .coeff = set.loads[3]},
829	                                         {.description = "Port 4 open", .filename = "P4_OPEN.s1p", .coeff = set.opens[4]},
830	                                         {.description = "Port 4 short", .filename = "P4_SHORT.s1p", .coeff = set.shorts[4]},
831	                                         {.description = "Port 4 load", .filename = "P4_LOAD.s1p", .coeff = set.loads[4]},
832	                                         {.description = "Port 1 to 2 through", .filename = "P12_THROUGH.s2p", .coeff = set.throughs[set.portsToThroughIndex(1,2)]},
833	                                         {.description = "Port 1 to 3 through", .filename = "P13_THROUGH.s2p", .coeff = set.throughs[set.portsToThroughIndex(1,3)]},
834	                                         {.description = "Port 1 to 4 through", .filename = "P14_THROUGH.s2p", .coeff = set.throughs[set.portsToThroughIndex(1,4)]},
835	                                         {.description = "Port 2 to 3 through", .filename = "P23_THROUGH.s2p", .coeff = set.throughs[set.portsToThroughIndex(2,3)]},
836	                                         {.description = "Port 2 to 4 through", .filename = "P24_THROUGH.s2p", .coeff = set.throughs[set.portsToThroughIndex(2,4)]},
837	                                         {.description = "Port 3 to 4 through", .filename = "P34_THROUGH.s2p", .coeff = set.throughs[set.portsToThroughIndex(3,4)]},
838	                                         }};
839	        for(const Coeff &c : coeffs) {
840	            addStatus("Loading coefficient ("+c.description+")...");
841	            try {
842	                auto t = Touchstone::fromFile(c.filename.toStdString());
843	                c.coeff->t = t;
844	                c.coeff->modified = true;
845	                QFile rmfile(c.filename);
846	                rmfile.remove();
847	            } catch (const std::exception &e) {
848	                abortWithError("Failed: "+QString::fromStdString(e.what()));
849	                return;
850	            }
851	        }
852	        // delete previous factory set if available
853	        for(unsigned int i=0;i<coeffSets.size();i++) {
854	            if(coeffSets[i].name == "FACTORY") {
855	                coeffSets.erase(coeffSets.begin() + i);
856	            }
857	        }
858	        // add set to device
859	        coeffSets.push_back(set);
860	        // enable factory writing on device
861	        addStatus("Enable factory coefficient writes...");
862	        bool success = usb->Cmd(":FACT:ENABLEWRITE I_AM_SURE");
863	        // delete all factory coefficients (this formats the factory partition)
864	        success &= usb->Cmd(":FACT:DEL", 5000);
865	
866	        if(success) {
867	            // start the transfer
868	            addStatus("Transferring new coefficients to LibreCAL...");
869	            // potential communication failures should not be passed on during this
870	            disconnect(usb, &USBDevice::communicationFailure, this, &CalDevice::disconnected);
871	            saveCoefficientSets();
872	        } else {
873	            abortWithError("Failed to erase previous factory calibration");
874	        }
875	    };
876	
877	    auto netw = new QNetworkAccessManager();
878	    connect(netw, &QNetworkAccessManager::finished, this, [=](QNetworkReply *reply) {
879	        if(reply->error() == QNetworkReply::NoError) {
880	            // success
881	            addStatus("Factory coefficients downloaded...");
882	            QFile file(serial()+".zip");
883	            if(!file.open(QIODevice::WriteOnly)) {
884	                abortWithError("Failed to create folder for zipped data");
885	                return;
886	            }
887	            file.write(reply->readAll());
888	            file.flush();
889	            file.close();
890	            updateFromFile(serial()+".zip");
891	            // remove zip file
892	            file.remove();
893	        } else {
894	            abortWithError("No factory coefficients found. Check internet access and serial number");
895	        }
896	    });
897	
898	    connect(ui->startUpdate, &QPushButton::clicked, this, [=](){
899	        ui->msg->clear();
900	        ui->startUpdate->setEnabled(false);
901	        ui->updateFile->setEnabled(false);
902	        ui->updateServer->setEnabled(false);
903	        ui->file->setEnabled(false);
904	        ui->browse->setEnabled(false);
905	        if(ui->updateServer->isChecked()) {
906	            addStatus("Looking up factory coefficient data...");
907	            QUrl url("https://librecal.kaeberich.com/calibrationdata/"+serial()+".zip");
908	            netw->get(QNetworkRequest(url));
909	        } else {
910	            // update from file
911	            updateFromFile(ui->file->text());
912	        }
913	    });
914	
915	    updateEnableState();
916	
917	    d->exec();
