31	    SearchDevices([=](libusb_device_handle *handle, QString found_serial) -> bool {
32	        if(serial.isEmpty() || serial == found_serial) {
33	            // accept connection to this device
34	            m_serial = found_serial;
35	            m_handle = handle;
36	            // abort device search
37	            return false;
38	        } else {
39	            // not the requested device, continue search
40	            return true;
41	        }
42	    }, m_context, false);
43	
44	    if(!m_handle) {
45	        QString message =  "No device found";
46	        if(!serial.isEmpty()) {
47	            // only show error message if specific device was requested
48	            InformationBox::ShowError("Error opening device", message);
49	        }
50	        libusb_exit(m_context);
51	        throw std::runtime_error(message.toStdString());
52	        return;
53	    }
54	
55	    // Found the correct device, now connect
56	    /* claim the interface */
57	    int ret = libusb_claim_interface(m_handle, 2);
58	    if (ret < 0) {
59	        libusb_close(m_handle);
60	        /* Failed to open */
61	        QString message =  "Failed to claim interface: \"";
62	        message.append(libusb_strerror((libusb_error) ret));
63	        message.append("\" Maybe you are already connected to this device?");
64	        qWarning() << message;
65	        InformationBox::ShowError("Error opening device", message);
66	        libusb_exit(m_context);
