118	            // auto port, to be determined later
119	            usedCalPorts.insert(port);
120	            // skip duplicate selection
121	            continue;
122	        } else if(port < 1) {
123	            // skip unused ports
124	            continue;
125	        }
126	        if(usedCalPorts.count(port)) {
127	            status = "LibreCAL port "+QString::number(port)+" is assigned to multiple VNA ports.";
128	            canStart = false;
129	            break;
130	        } else {
131	            usedCalPorts.insert(port);
132	        }
