153	    double coeffMinFreq = numeric_limits<double>::max();
154	    double coeffMaxFreq = numeric_limits<double>::lowest();
155	
156	    auto checkCoefficient = [&](CalDevice::CoefficientSet::Coefficient *c) -> bool {
157	        if(!c) {
158	            return false;
159	        }
160	        if(c->t.points() == 0) {
161	            return false;
162	        } else {
163	            if(c->t.minFreq() < coeffMinFreq) {
164	                coeffMinFreq = c->t.minFreq();
165	            }
166	            if(c->t.maxFreq() > coeffMaxFreq) {
167	                coeffMaxFreq = c->t.maxFreq();
168	            }
169	            return true;
170	        }
171	    };
172	
173	    set<int> usedCalPorts;
174	    // Check port mapping for duplicate entries (and at least one used port)
175	    for(auto port : portAssignment) {
176	        if(port > 0) {
177	            usedCalPorts.insert(port);
178	        }
179	    }
180	
181	    // check if coefficients for all ports are available
182	    for(auto i : usedCalPorts) {
183	        // Check if OSL coefficients are there
184	        if(!checkCoefficient(coeffSet.getOpen(i))) {
185	            status = "Open coefficient for LibreCAL port "+QString::number(i)+" is missing.";
186	            canStart = false;
187	            break;
188	        }
189	        if(!checkCoefficient(coeffSet.getShort(i))) {
190	            status = "Short coefficient for LibreCAL port "+QString::number(i)+" is missing.";
191	            canStart = false;
192	            break;
193	        }
194	        if(!checkCoefficient(coeffSet.getLoad(i))) {
195	            status = "Load coefficient for LibreCAL port "+QString::number(i)+" is missing.";
196	            canStart = false;
197	            break;
198	        }
199	        for(auto j : usedCalPorts) {
200	            if(j <= i) {
201	                continue;
202	            }
203	            if(!checkCoefficient(coeffSet.getThrough(i,j))) {
204	                status = "Through coefficient for LibreCAL port "+QString::number(i)+" to "+QString::number(j)+" is missing.";
205	                canStart = false;
206	                break;
207	            }
208	        }
209	    }
210	    if(!canStart) {
211	        ui->lCalibrationStatus->setText(status);
212	        ui->lCalibrationStatus->setStyleSheet("QLabel { color : red; }");
213	    }
214	    return canStart;
215	}
