274	void LibreCALDialog::determineAutoPorts()
275	{
276	    disableUI();
277	    ui->progressCal->setValue(0);
278	    ui->lCalibrationStatus->setText("Autodetecting port connections...");
279	    ui->lCalibrationStatus->setStyleSheet("QLabel { color : green; }");
280	
281	    // check if any ports are set to auto
282	    bool usesAuto = false;
283	    for(auto port : portAssignment) {
284	        if(port == -1) {
285	            usesAuto = true;
286	            break;
287	        }
288	    }
289	    if(usesAuto) {
290	        driver = DeviceDriver::getActiveDriver();
291	        emit driver->acquireControl();
292	        // Determine ports by setting all ports to open and then switching them to short one at a time while observing the change in the VNA measurement
293	        for(unsigned int i=1;i<=device->getNumPorts();i++) {
294	            device->setStandard(i, CalDevice::Standard::Type::Open);
295	        }
296	        autoPortMeasurements.clear();
297	        startSweep();
298	    } else {
299	        // no auto ports
300	        emit autoPortComplete();
301	    }
302	}
