304	void LibreCALDialog::loadCoefficients()
305	{
306	    // validate ports again, at this point no "auto" selection is allowed anymore
307	    if(!validatePortSelection(false)) {
308	        enableUI();
309	        updateCalibrationStartStatus();
310	    } else {
311	        // can continue with loading coefficients
312	        // they might already be loaded from a previous calibration run, check first
313	        if(!validateCoefficients()) {
314	            // only load required coefficients
315	            ui->progressCal->setValue(0);
316	            ui->lCalibrationStatus->setText("Loading coefficients...");
317	            ui->lCalibrationStatus->setStyleSheet("QLabel { color : green; }");
318	
319	            // determine the used ports of the LibreCAL
320	            QList<int> usedPorts;
321	            for(auto port : portAssignment) {
322	                if(port > 0) {
323	                    usedPorts.append(port);
324	                }
325	            }
326	
327	            busy = true;            
328	            device->loadCoefficientSets({ui->cbCoefficients->currentText()}, usedPorts);
329	        } else {
