336	void LibreCALDialog::handleIncomingMeasurement(DeviceDriver::VNAMeasurement m)
337	{
338	    stopSweep();
339	    autoPortMeasurements.push_back(m);
340	    auto nextPort = autoPortMeasurements.size();
341	    // switch LibreCAL to next port
342	    if(nextPort <= device->getNumPorts()) {
343	        device->setStandard(nextPort, CalDevice::Standard::Type::Short);
344	    }
345	    if(nextPort > 1) {
346	        device->setStandard(nextPort-1, CalDevice::Standard::Type::Open);
347	    }
348	    if(nextPort > device->getNumPorts()) {
349	        // auto port measurements complete
350	
351	        // reset LibreCAL ports
352	        for(unsigned int i=1;i<=device->getNumPorts();i++) {
353	            device->setStandard(i, CalDevice::Standard::Type::None);
354	        }
355	        // evaluate results
356	        for(unsigned int p=0;p<portAssignment.size();p++) {
357	            auto port = portAssignment[p];
358	            if(port != -1) {
359	                // not set to auto, ignore
360	                continue;
361	            }
362	            auto param = "S"+QString::number(p+1)+QString::number(p+1);
363	            std::vector<std::complex<double>> measurements;
364	            for(auto m : autoPortMeasurements) {
365	                if(m.measurements.count(param)) {
366	                    measurements.push_back(m.measurements[param]);
367	                }
368	            }
369	            if(measurements.size() != device->getNumPorts()+1) {
370	                // not all measurements available (maybe the port has no stimulus?), set to unused
371	                portAssignmentComboBoxes[p]->setCurrentIndex(0);
372	                continue;
373	            }
374	            // got all required measurements, determine which one deviates the most from the baseline
375	            double maxDeviation = 0.0;
376	            int maxDevIndex = 0;
377	            for(unsigned int i=1;i<=device->getNumPorts();i++) {
378	                auto diff = abs(measurements[i] - measurements[0]);
379	                if (diff > maxDeviation) {
380	                    maxDeviation = diff;
381	                    maxDevIndex = i;
382	                }
383	            }
384	            constexpr double minRequiredDeviation = 0.25;
385	            if(maxDeviation > minRequiredDeviation) {
386	                portAssignmentComboBoxes[p]->setCurrentIndex(maxDevIndex+1);
387	            } else {
388	                // not enough deviation, probably unused
389	                portAssignmentComboBoxes[p]->setCurrentIndex(0);
390	            }
391	        }
392	        emit driver->releaseControl();
393	        emit autoPortComplete();
394	    } else {
395	        // trigger the next measurement
396	        startSweep();
397	    }
398	}
