400	void LibreCALDialog::startSweep()
401	{
402	    // set up a sweep with a single measurement point at the start frequency
403	    auto info = driver->getInfo();
404	    DeviceDriver::VNASettings s = {};
405	    s.dBmStart = info.Limits.VNA.maxdBm;
406	    s.dBmStop = info.Limits.VNA.maxdBm;
407	
408	    auto freq = info.Limits.VNA.minFreq == 0 ? 100000 : info.Limits.VNA.minFreq;
409	
410	    s.freqStart = freq;
411	    s.freqStop = freq;
412	    s.IFBW = 100;
413	    s.logSweep = false;
414	    s.points = 1;
415	
416	    for(unsigned int i=1;i<=info.Limits.VNA.ports;i++) {
417	        s.excitedPorts.push_back(i);
418	    }
419	    driver->setVNA(s, [=](bool){
420	        connect(driver, &DeviceDriver::VNAmeasurementReceived, this, &LibreCALDialog::handleIncomingMeasurement, Qt::DirectConnection);
421	    });
422	}
