430	void LibreCALDialog::startCalibration()
431	{
432	    disableUI();
433	    busy = true;
434	
435	    ui->progressCal->setValue(0);
436	    ui->lCalibrationStatus->setText("Creating calibration kit from coefficients...");
437	    ui->lCalibrationStatus->setStyleSheet("");
438	    auto& kit = cal->getKit();
439	    kit.clearStandards();
440	    kit.manufacturer = "LibreCAL ("+coeffSet.name+")";
441	    kit.serialnumber = device->serial();
442	    kit.description = "Automatically created from LibreCAL module";
443	
444	    // determine the used ports of the LibreCAL
445	    QList<int> usedPorts;
446	    for(auto port : portAssignment) {
447	        if(port > 0) {
448	            usedPorts.append(port);
449	        }
450	    }
451	    std::sort(usedPorts.begin(), usedPorts.end());
452	
453	    std::map<int, CalStandard::Virtual*> openStandards;
454	    std::map<int, CalStandard::Virtual*> shortStandards;
455	    std::map<int, CalStandard::Virtual*> loadStandards;
456	    std::map<int, CalStandard::Virtual*> throughStandards;
457	    for(unsigned int idx=0;idx<usedPorts.size();idx++) {
458	        int i=usedPorts[idx];
459	        if(coeffSet.getOpen(i)->t.points() > 0) {
460	            auto o = new CalStandard::Open();
461	            o->setName("Port "+QString::number(i));
462	            o->setMeasurement(coeffSet.getOpen(i)->t);
463	            openStandards[i] = o;
464	            kit.addStandard(o);
465	        }
466	        if(coeffSet.getShort(i)->t.points() > 0) {
467	            auto o = new CalStandard::Short();
468	            o->setName("Port "+QString::number(i));
469	            o->setMeasurement(coeffSet.getShort(i)->t);
470	            shortStandards[i] = o;
471	            kit.addStandard(o);
472	        }
473	        if(coeffSet.getLoad(i)->t.points() > 0) {
474	            auto o = new CalStandard::Load();
475	            o->setName("Port "+QString::number(i));
476	            o->setMeasurement(coeffSet.getLoad(i)->t);
477	            loadStandards[i] = o;
478	            kit.addStandard(o);
479	        }
480	        for(unsigned int jdx=idx+1;jdx<usedPorts.size();jdx++) {
481	            int j=usedPorts[jdx];
482	            auto c = coeffSet.getThrough(i,j);
483	            if(!c) {
484	                continue;
485	            }
486	            if(c->t.points() > 0) {
487	                auto o = new CalStandard::Through();
488	                o->setName("Port "+QString::number(i)+" to "+QString::number(j));
489	                o->setMeasurement(c->t);
490	                throughStandards[coeffSet.portsToThroughIndex(i, j)] = o;
491	                kit.addStandard(o);
492	            }
493	        }
494	    }
495	    ui->lCalibrationStatus->setText("Creating calibration measurements...");
496	    cal->reset();
497	    auto vnaPorts = DeviceDriver::getInfo(DeviceDriver::getActiveDriver()).Limits.VNA.ports;
498	    set<CalibrationMeasurement::Base*> openMeasurements;
499	    set<CalibrationMeasurement::Base*> shortMeasurements;
500	    set<CalibrationMeasurement::Base*> loadMeasurements;
501	    vector<CalibrationMeasurement::TwoPort*> throughMeasurements;
502	    for(unsigned int p=0;p<vnaPorts;p++) {
503	        if(portAssignment[p] == 0) {
504	            continue;
505	        }
506	        // Create SOL measurements with correct port of calkit
507	        auto open = new CalibrationMeasurement::Open(cal);
508	        open->setPort(p+1);
509	        open->setStandard(openStandards[portAssignment[p]]);
510	        openMeasurements.insert(open);
511	        cal->measurements.push_back(open);
512	
513	        auto _short = new CalibrationMeasurement::Short(cal);
514	        _short->setPort(p+1);
515	        _short->setStandard(shortStandards[portAssignment[p]]);
516	        shortMeasurements.insert(_short);
517	        cal->measurements.push_back(_short);
518	
519	        auto load = new CalibrationMeasurement::Load(cal);
520	        load->setPort(p+1);
521	        load->setStandard(loadStandards[portAssignment[p]]);
522	        loadMeasurements.insert(load);
523	        cal->measurements.push_back(load);
524	        for(unsigned int p2=p+1;p2<vnaPorts;p2++) {
525	            if(portAssignment[p2] == 0) {
526	                continue;
527	            }
528	            auto through = new CalibrationMeasurement::Through(cal);
529	            through->setPort1(p+1);
530	            through->setPort2(p2+1);
531	            // find correct through standard
532	            int libreCALp1 = portAssignment[p];
533	            int libreCALp2 = portAssignment[p2];
534	            QString forwardName = "Port "+QString::number(libreCALp1)+" to "+QString::number(libreCALp2);
535	            QString reverseName = "Port "+QString::number(libreCALp2)+" to "+QString::number(libreCALp1);
536	            for(auto ts : throughStandards) {
537	                if(ts.second->getName() == forwardName) {
538	                    through->setStandard(ts.second);
539	                    through->setReverseStandard(false);
540	                } else if(ts.second->getName() == reverseName) {
541	                    through->setStandard(ts.second);
542	                    through->setReverseStandard(true);
543	                }
544	            }
545	            throughMeasurements.push_back(through);
546	            cal->measurements.push_back(through);
547	        }
548	    }
549	
550	    ui->lCalibrationStatus->setText("Taking calibration measurements...");
551	
552	    measurementsTaken = 0;
553	
554	    auto setTerminationOnAllUsedPorts = [=](CalDevice::Standard s) {
555	        for(auto p : portAssignment) {
556	            if(p > 0) {
557	                device->setStandard(p, s);
558	            }
559	        }
560	    };
561	
562	    auto startNextCalibrationStep = [=]() {
563	        // indicate calibration percentage
564	        auto totalMeasurements = 3 + throughMeasurements.size();
565	        ui->progressCal->setValue(measurementsTaken * 100 / totalMeasurements);
566	        switch(measurementsTaken) {
567	        case 0:
568	            setTerminationOnAllUsedPorts(CalDevice::Standard(CalDevice::Standard::Type::Open));
569	            emit cal->startMeasurements(openMeasurements);
570	            break;
571	        case 1:
572	            setTerminationOnAllUsedPorts(CalDevice::Standard(CalDevice::Standard::Type::Short));
573	            emit cal->startMeasurements(shortMeasurements);
574	            break;
575	        case 2:
576	            setTerminationOnAllUsedPorts(CalDevice::Standard(CalDevice::Standard::Type::Load));
577	            emit cal->startMeasurements(loadMeasurements);
578	            break;
579	        default: {
580	            // into through measurements now
581	            unsigned int throughIndex = measurementsTaken - 3;
582	            if(throughIndex >= throughMeasurements.size()) {
583	                // this was the last measurement
584	                // Try to apply the calibration
585	                Calibration::CalType type;
586	                type.type = Calibration::Type::SOLT;
587	                for(unsigned int i=0;i<vnaPorts;i++) {
588	                    if(portAssignment[i] > 0) {
589	                        // this VNA port was used in the calibration
590	                       type.usedPorts.push_back(i+1);
591	                    }
592	                }
593	                auto res = cal->compute(type);
594	                if(res) {
595	                    ui->progressCal->setValue(100);
596	                    ui->lCalibrationStatus->setText("Calibration activated.");
597	                } else {
598	                    ui->progressCal->setValue(0);
599	                    ui->lCalibrationStatus->setText("Failed to activate calibration.");
600	                    ui->lCalibrationStatus->setStyleSheet("QLabel { color : red; }");
601	                }
602	                // sever connection to this function
603	                disconnect(cal, &Calibration::measurementsUpdated, this, nullptr);
604	                setTerminationOnAllUsedPorts(CalDevice::Standard(CalDevice::Standard::Type::None));
605	                enableUI();
606	                busy = false;
607	                break;
608	            }
609	            setTerminationOnAllUsedPorts(CalDevice::Standard(CalDevice::Standard::Type::None));
610	            auto m = throughMeasurements[throughIndex];
611	            device->setStandard(portAssignment[m->getPort1()-1], CalDevice::Standard(portAssignment[m->getPort2()-1]));
612	            emit cal->startMeasurements({m});
613	        }
614	            break;
615	        }
616	        measurementsTaken++;
617	    };
618	
619	    disconnect(cal, &Calibration::measurementsUpdated, this, nullptr);
620	    connect(cal, &Calibration::measurementsUpdated, this, startNextCalibrationStep, Qt::QueuedConnection);
621	    connect(cal, &Calibration::measurementsAborted, this, [=](){
622	        setTerminationOnAllUsedPorts(CalDevice::Standard(CalDevice::Standard::Type::None));
623	        enableUI();
624	        busy = false;
625	        ui->lCalibrationStatus->setText("Ready to start");
626	    });
627	
628	    startNextCalibrationStep();
629	}
