651	void LibreCALDialog::createPortAssignmentUI()
652	{
653	    auto layout = static_cast<QFormLayout*>(ui->assignmentBox->layout());
654	    // Clear any possible previous elements
655	    portAssignment.clear();
656	    portAssignmentComboBoxes.clear();
657	    while(layout->rowCount() > 1) {
658	        layout->removeRow(1);
659	    }
660	    auto vnaPorts = DeviceDriver::getInfo(DeviceDriver::getActiveDriver()).Limits.VNA.ports;
661	    portAssignment.resize(vnaPorts, 0);
662	    auto calPorts = 0;
663	    if(device) {
664	        calPorts = device->getNumPorts();
665	    }
666	    QStringList choices = {"Unused", "Auto"};
667	    for(int i=1;i<=calPorts;i++) {
668	        choices.push_back("Port "+QString::number(i));
669	    }
670	    for(unsigned int p = 1;p<=vnaPorts;p++) {
671	        auto label = new QLabel("Port "+QString::number(p)+":");
672	        auto comboBox = new QComboBox();
673	        comboBox->addItems(choices);
674	        connect(comboBox, qOverload<int>(&QComboBox::currentIndexChanged), [=](){
675	            if(comboBox->currentText().startsWith("Unused")) {
676	                portAssignment[p-1] = 0;
677	            } else if(comboBox->currentText().startsWith("Auto")) {
678	                portAssignment[p-1] = -1;
679	            } else if(comboBox->currentText().startsWith("Port")) {
680	                portAssignment[p-1] = comboBox->currentText().back().digitValue();
681	            }
682	            emit portAssignmentChanged();
683	        });
684	        comboBox->setCurrentIndex(1);
685	        layout->addRow(label, comboBox);
686	        portAssignmentComboBoxes.push_back(comboBox);
687	    }
688	}
